from proto import *
def slump(a0=-146, a1=-176.5, r0=36.5, r1=31.5): return arcpts(lambda a: r0 + (r1-r0)*(a-a0)/(a1-a0), a0, a1)
def H_Z(tailR=34, tailA=-48, tip=[(24,-22),(20.5,-21)], headE=[(12,-28),(11.5,-38),(8,-48),(4,-58),(0,-65),(-4,-69)], headW=[(-24,-69),(-29,-66),(-33,-58),(-35,-48),(-35,-38),(-34,-28),(-30.3,-20.4)], sl=(36.5,31.5), endR=34):
    return arcpts(lambda a: tailR, 0, tailA) + tip + headE + headW + slump(r0=sl[0], r1=sl[1]) + [P(endR,-179.9)]
evaluate(H_Z(), 'z1')
